  _ = `Etkinlik URL'inin tamamını girin ve ardından otomatik tamamlama menüsünden seçim yapın. Etkinliğin eklenebilmesi için herkese görünür olması gereklidir.`,
  _ = `Etkinliği Tekrar Gönderin`,
  _ = `Tekrar Gönder`,
  _ = `Tekrar gönderme, etkinliği Haber Merkezi'ndeki seçili grupların akışlarında tekrar öne çıkartır. Aşağıdaki bu etkinliğin tekrar gönderilebileceği diğer topluluk grupları veya uygulamaları yer almaktadır. Göndermek için bir veya daha fazla grubu seçin.`,
