  _ = `Bu sayfa yayınlanmadan önce Valve tarafından incelenmesi gerekmektedir.`,
  _ = `Bu indirim sayfası Valve onayı beklemektedir.`,
  _ = `İncelemenin/onaylamanın ve gerekli değişikliklerin yapılabilmesine yeterince zaman tanımak için lütfen arzu ettiğiniz yayın tarihinden en az 7 gün önce sağdaki butonu kullanarak sayfanızı inceleme için gönderin.`,
  _ = `Sayfanızda yapılması gereken herhangi bir değişiklik olursa, Steam ekibi sizinle Steamworks Destek yardım talebi aracılığıyla irtibata geçer. Sağdaki butona tıklayarak Steamworks Destek yardım talebinizi görüntüleyebilir veya gerekirse buna yorum ekleyebilirsiniz.`,
  _ = `Sayfayı onaylandı olarak işaretlemek partnerin indirimi yayınlamasına ve herkese görünür yapmasına izin verecektir`,
  _ = `İnceleme Talep Et...`,
  _ = `İnceleme Talep Et`,
  _ = `İndirim sayfası yayınlama onayı için inceleme talebi oluşturur. Bunu, indirim sayfanız son çizimleri ve öne çıkarmak istediğiniz tüm oyunları içerdiğinde yapın.`,
  _ = `Bu, indirim sayfanızın Valve tarafından incelenmesini talep eden bir Steamworks Destek talebi oluşturur. Bu sadece sayfadaki çizimleriniz ve mesajınız kesinleştikten ve oyun listeniz tamamlandıktan sonra yapılmalıdır.`,
  _ = `Lütfen etkinlik başlığınızın ve amacınızın sayfanın üst kısmında açıkça belirtildiğinden emin olun. Vitrinler için sayfanızın üst kısmında vitrininizin ne olduğunu ve nasıl çalıştığını açıklayan bir metin bölümüne ihtiyacınız olabilir.`,
  _ = `İndirim sayfası incelendikten sonra kilitlenecektir. İncelemeden sonra veya etkinlik başladıktan sonra değişiklik yapmanız gerekirse lütfen yorum kısmına bu değişikliklerin neleri içerdiğini ve incelemeden önce neden tamamlanamadığını yazın.`,
  _ = `İsteğe bağlı: İnceleme ekibi için eklemek istediğiniz bilgiler.`,
  _ = `Üyelerinin de talebe erişebileceği partnerleri seçin`,
  _ = `İsteğe bağlı: Seçilirse partnerlerin diğer üyeleri talebe erişebilir ve yanıt verebilir. Varsayılan olarak, oluşturulan talebi yalnızca siz okuyabilir, güncelleyebilir ve yanıtlayabilirsiniz.`,
  _ = `Talep oluşturulamadı, lütfen daha sonra tekrar deneyin`,
  _ = `Bu türde bir destek talebi zaten mevcut olduğu için yeni bir destek talebi oluşturulamıyor. Lütfen bu talebi göndermeden önce diğer indirim sayfanızın incelemesini tamamlayın veya açık destek talebini bu sayfanın da incelemesini içerecek şekilde güncelleyin.`,
  _ = `Talep başarıyla oluşturuldu!`,
  _ = `İnceleme Yardım Talebini Görüntüle...`,
  _ = `Sayfanız onaylandı ve yayınlanmaya hazır.`,
  _ = `Yayınlama süreci için "Yayınlama" sekmesine geçin.`,
