  _ = `Kurallar ve Yönergeler`,
  _ = `Bu oyun hakkında neyi sevip neyi sevmediğinizi ve bu oyunu başkalarına önerip önermeyeceğinizi yazın. Lütfen kibar olmayı ve %1$s doğrultusunda hareket etmeyi unutmayın.`,
  _ = `Bu incelemeyi göndererek, bu yorumu yazdığınız konumun, diğer Steam China kullanıcılarıyla paylaşılacağını kabul ediyorsunuz.`,
