  _ = `Büyük Güncelleme Pazarlama Mesajı`,
  _ = `Hedef kitleniz için ilgi çekici ve uygun bir başlık seçin. Yılın en büyük güncellemelerinden birini yayınlayacaksanız başlık da bu heyecanı yansıtmalıdır. <1>Sürüm 330.4 Güncellemesi</1> gibi genel ifadelerden kaçının. Bunun yerine, bu güncellemeyi özel kılan unsurları vurgulayın.`,
  _ = `Ana görsel, güncellemeyi vurgulamalıdır. Oyununuzun standart görselini olduğu gibi kullanmayın. Kullanıcılar, bunun yeni ve önemli bir şeyi temsil ettiğini hemen anlamalıdır.`,
  _ = `Etkinlik açıklaması, güncellemeyi ve neden önemli olduğunu açıklayacak şekilde özenle hazırlanmalıdır. Bu fırsatı, oyuncuları geri gelmeye teşvik etmek için kullanın:`,
  _ = `Yeni ve ilgi çekici içerikleri öne çıkarın.`,
  _ = `Görselleri, fragmanları veya kısa klipleri yaratıcı bir şekilde kullanın.`,
  _ = `Oyunculara ilgi duymaları, geri gelmeleri ve etkileşimde bulunmaları için gerekçe sunun.`,
  _ = `Bu sadece güncellemenizi duyurmak için değil, aynı zamanda tanıtımını yapmak için de bir fırsattır.`,
