  _ = `true olarak ayarlandığında, etkinlik organizatörlerinin etkinliğe kimlerin ev sahipliği yaptığını belirtmesi gerekir. Bu, etkinliği kimin düzenlediğinin açıkça bilinmesi ve müşterilerin etkinliğin Valve tarafından düzenlendiğini sanmansını önlemek adına müşteriye dönük satış sayfasında görüntülenir.`,
