  _ = `Arkanıza Yaslanın ve Rahatlayın`,
  _ = `Spesifik kategoriler tavsiye etmek yerine hayranlarınızın oyununuz için en uygun kategoriyi seçmesine izin verin. Etkinlikte adaylar sayfasına yönlendiren bir bağlantı olacak.`,
  _ = `Kategori Yok`,
  _ = `Sizi etkileyen şey sürükleyici oynanışı, saran hikâyesi, oldukça iyi oluşturulmuş karakterleri, kusursuz tasarımı ya da bağımlılık yaratan çok oyunculu moduydu. Gerekçeniz ne olursa olsun 2020'un En İyi Oyunu ödülünü kazanan oyun tamamen harika bir oyun olacak.`,
  _ = `Yılın VR oyunu normal gerçekliği taklit etmekle kalmıyor, gerçekliğimizi bir üst seviyeye taşıyor. VR platformunu tam anlamıyla kullanan bu oyun sanal diyarların sınırlarını zorluyor.`,
  _ = `Bu oyun çıkalı çok oldu. Geliştirici ekibin, yaratıcı fikirlerini hayata geçirdikleri göz bebeklerini duyurduğu ilk günün üzerinden uzun zaman geçti ama geliştiriciler, tıpkı iyi birer anne ve baba gibi eserlerini desteklemeye ve büyütmeye devam etti. Bu oyun, geçen tüm yıllara inat, bugün bile yeni içerik almaya devam ediyor.`,
  _ = `Bazı harika oyunlar, tek başına oynandığında o kadar da harika olmayabilir. Arkanızı kollaması için belki de birkaç arkadaşa ihtiyacınız vardır. Belki de sırtından bıçaklayabileceğiniz birkaç arkadaşa ihtiyacınız vardır. Her iki şekilde de bu oyunları oynamak için arkadaşlarıyla toplananları neşe beklemektedir.`,
  _ = `Görsel stil gerçek dünyadaki görselliği hedef almaz (kendi içinde asil bir ülkü olsa da)... Görsel stil, bütün bir oyunu dolduracak belirgin görünüm ve hissi yansıtır.`,
  _ = `Bu oyunun tasarımcıları getirdikleri yeni perspektifler ve akıllara durgunluk veren sürprizler ile yenilikçi deneylerin birer neferi konumundalar. Bu oyun, içerdiği yenilikler ile daha önce hiç olmadığı kadar eğlendirdi ve ilham verdi.`,
  _ = `Bu, inatçılığı ödüllendiren oyun sinirlerine hâkim olamayanlar için hiç uygun değil. Sevdiğimiz en zor oyun.`,
  _ = `Bu oyuna eşlik eden harikulade müzikler sizi mest etti. Daha iyisi yok! `,
  _ = `Bazı günler sadece hikâye yönü ağır basan oyunlar sizi tatmin edebilir ve bu oyun da tam böylesi bir oyun. İzlediğiniz en etkileyici diziler kadar sizi içine çekecek ve çığır açıcı diziler kadar da cesur bir hikâyeye sahip. Bizi derinden etkilediğin için çok teşekkürler!`,
  _ = `Bu oyun yorucu bir günün âdeta panzehri. Bu akıcı ve rahatlatıcı oyun sayesinde bütün dertleriniz uçup gidiyor. Bu oyun size dinginliği yaşatıyor.`,
  _ = `Adayınızı değiştirmek mi istiyorsunuz?`,
  _ = `Her kategori için sadece tek bir oyunu aday gösterebilirsiniz. Bu kategori için %1$s adlı oyunu zaten aday göstermişsiniz. Adayınızı %2$s olarak değiştirmek ister misiniz?`,
