  _ = `Hesabınız kısıtlı. Steam Ödülleri'ne katılabilmeniz ve aday göstermede kötüye kullanımın önüne geçmek için Steam'de 5 USD harcamalısınız. Daha fazla bilgi için %1$s.`,
